package com.example.bluetoothtest

/** Loader of the shared vector file `wifi-vectors.json` (generated by tools/wifi_reference.py; never edit it). */
internal object WifiVectors {
    fun hex(text: String): ByteArray = ByteArray(text.length / 2) { text.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    fun hex(bytes: ByteArray): String = bytes.joinToString("") { "%02x".format(it.toInt() and 0xff) }

    @Suppress("UNCHECKED_CAST")
    val root: Map<String, Any?> by lazy {
        val text = checkNotNull(WifiVectors::class.java.classLoader!!.getResourceAsStream("wifi-vectors.json")) {
            "missing test resource wifi-vectors.json"
        }.use { String(it.readBytes(), Charsets.UTF_8) }
        TestJson.parse(text) as Map<String, Any?>
    }

    @Suppress("UNCHECKED_CAST")
    fun section(name: String): Map<String, Any?> = root.getValue(name) as Map<String, Any?>

    @Suppress("UNCHECKED_CAST")
    fun list(name: String): List<Map<String, Any?>> = root.getValue(name) as List<Map<String, Any?>>

    fun text(map: Map<String, Any?>, key: String): String = map.getValue(key) as String

    fun bytes(map: Map<String, Any?>, key: String): ByteArray = hex(text(map, key))
}
